//! `cargo xtask docs-inventory`: regenerate `docs/generated/` deterministically
//! (a CON-9 gate step; TRC-20 and LOOP-30 extend it later). `--check` fails
//! when the committed files differ from what would be generated.

use std::collections::BTreeMap;
use std::fmt::Write as _;
use std::path::Path;

use serde::Serialize;

use crate::model::Model;
use crate::specs::Level;
use crate::workspace::{read, write};
use crate::{Error, Result};

/// Directory (relative to the root) that this task owns.
pub const GENERATED_DIR: &str = "docs/generated";

const HEADER: &str =
    "<!-- Generated by `cargo xtask docs-inventory`. Do not edit; regenerate. -->\n\n";

/// The JSON object `docs-inventory` prints (CON-8).
#[derive(Debug, Serialize)]
pub struct Report {
    pub ok: bool,
    pub mode: &'static str,
    pub written: Vec<String>,
    pub changed: Vec<String>,
    pub stale: Vec<String>,
    pub removed: Vec<String>,
    /// TRC-20: `acn.*` names that a crate emits and the inventory does not list.
    /// Any entry fails the task, in write mode as well as in check mode.
    pub unlisted_attributes: Vec<crate::attributes::Unlisted>,
}

fn md_escape(s: &str) -> String {
    s.replace('|', "\\|")
}

fn requirements_md(model: &Model) -> String {
    let by_id = model.citations_by_id();
    let mut s = String::from(HEADER);
    s.push_str("# Requirement inventory\n\n");
    let _ = writeln!(
        s,
        "Specs: {} · IDs: {} · MUSTs: {} · implemented: {} · cited: {}\n",
        model.spec_count,
        model.requirements.len(),
        model
            .requirements
            .iter()
            .filter(|r| r.level == Level::Must)
            .count(),
        model.implemented.len(),
        by_id.len()
    );
    s.push_str("| ID | Spec | § | Level | Implemented | Cited by |\n|---|---|---|---|---|---|\n");
    for r in &model.requirements {
        let level = match r.level {
            Level::Must => "MUST",
            Level::Should => "SHOULD",
            Level::May => "MAY",
            Level::None => "—",
        };
        let implemented = if model.implemented.contains(&r.id) {
            "yes"
        } else {
            "no"
        };
        let cited = by_id
            .get(r.id.as_str())
            .map(|cs| {
                cs.iter()
                    .map(|c| {
                        format!(
                            "`{}` {}",
                            c.file,
                            c.function
                                .as_deref()
                                .map(|f| format!("`{f}`"))
                                .unwrap_or_default()
                        )
                    })
                    .collect::<Vec<_>>()
                    .join("<br>")
            })
            .unwrap_or_else(|| "—".to_owned());
        let _ = writeln!(
            s,
            "| {} | `{}` | {} | {} | {} | {} |",
            r.id,
            r.file,
            r.section.as_deref().unwrap_or("—"),
            level,
            implemented,
            md_escape(&cited)
        );
    }
    s
}

fn field<'a>(text: &'a str, key: &str) -> Option<&'a str> {
    let start = text.find(key)? + key.len();
    let rest = text[start..].lines().next().unwrap_or("");
    let end = rest.find("**").unwrap_or(rest.len());
    Some(rest[..end].trim().trim_end_matches('.'))
}

/// File names in `dir` accepted by `keep`, sorted; every listing error is reported.
fn names_in(dir: &Path, keep: impl Fn(&str) -> bool) -> Result<Vec<String>> {
    let mut names = Vec::new();
    if dir.is_dir() {
        for entry in std::fs::read_dir(dir).map_err(|e| Error::io(dir, e))? {
            let entry = entry.map_err(|e| Error::io(dir, e))?;
            let name = entry.file_name().to_string_lossy().into_owned();
            if keep(&name) {
                names.push(name);
            }
        }
    }
    names.sort();
    Ok(names)
}

fn h1_title(text: &str) -> &str {
    text.lines()
        .find_map(|l| l.strip_prefix("# "))
        .unwrap_or("")
        .trim()
}

fn decisions_md(root: &Path) -> Result<String> {
    let dir = root.join("docs/decisions");
    let mut names = names_in(&dir, |n| n.starts_with("ADR-") && n.ends_with(".md"))?;
    // Numeric order with the file name as tie-breaker, so `ADR-3` and `ADR-03`, or
    // two non-numeric names, never fall back to directory order, which differs by filesystem.
    names.sort_by_key(|n| {
        let number = n
            .trim_start_matches("ADR-")
            .trim_end_matches(".md")
            .parse::<u32>()
            .unwrap_or(u32::MAX);
        (number, n.clone())
    });
    let mut s = String::from(HEADER);
    s.push_str(
        "# Decision records\n\n| ADR | Title | Status | IDs affected |\n|---|---|---|---|\n",
    );
    for name in names {
        let text = read(&dir.join(&name))?;
        let stem = name.trim_end_matches(".md");
        let title = h1_title(&text)
            .split_once('—')
            .map_or_else(|| stem.to_owned(), |(_, t)| t.trim().to_owned());
        let status = field(&text, "**Status:**").unwrap_or("—");
        let ids = field(&text, "**IDs affected:**").unwrap_or("—");
        let _ = writeln!(
            s,
            "| [{stem}](../decisions/{name}) | {} | {} | {} |",
            md_escape(&title),
            md_escape(status),
            md_escape(ids)
        );
    }
    Ok(s)
}

fn lab_notes_md(root: &Path) -> Result<String> {
    let dir = root.join("docs/lab");
    let names = names_in(&dir, |n| n.ends_with(".md"))?;
    let mut s = String::from(HEADER);
    s.push_str("# Lab notes (CON-23)\n\n| Note | Title |\n|---|---|\n");
    if names.is_empty() {
        s.push_str("| — | no lab notes yet |\n");
    }
    for name in names {
        let text = read(&dir.join(&name))?;
        let _ = writeln!(
            s,
            "| [{}](../lab/{name}) | {} |",
            name.trim_end_matches(".md"),
            md_escape(h1_title(&text))
        );
    }
    Ok(s)
}

/// TRC-36: the report-coverage page, when the root holds SPEC 010. The mapping is
/// then required, and an unmapped key, an unknown key, or a column or attribute
/// the schema does not define fails the task.
fn report_coverage_md(root: &Path) -> Result<Option<String>> {
    use acn_trace::coverage::{self, Coverage};
    let spec = root.join(coverage::SPEC_FILE);
    if !spec.is_file() {
        return Ok(None);
    }
    let keys =
        coverage::appendix_a_keys(&read(&spec)?).map_err(|e| Error::Invalid(e.to_string()))?;
    let mapping = root.join(coverage::COVERAGE_FILE);
    if !mapping.is_file() {
        return Err(Error::Invalid(format!(
            "{} is missing: every Appendix A key of {} needs an entry (TRC-36)",
            coverage::COVERAGE_FILE,
            coverage::SPEC_FILE
        )));
    }
    let schema_err = |e: acn_trace::schema::SchemaError| Error::Invalid(e.to_string());
    let inv = acn_trace::schema::inventory().map_err(schema_err)?;
    let views = acn_trace::schema::views().map_err(schema_err)?;
    let cov = Coverage::parse(&read(&mapping)?, &keys, &views, &inv)
        .map_err(|e| Error::Invalid(e.to_string()))?;
    Ok(Some(format!("{HEADER}{}", cov.page())))
}

/// Generate every file, keyed by path relative to the root.
pub fn generate(root: &Path) -> Result<BTreeMap<String, String>> {
    let model = Model::load(root)?;
    let mut files = BTreeMap::new();
    files.insert(
        format!("{GENERATED_DIR}/requirements.md"),
        requirements_md(&model),
    );
    files.insert(format!("{GENERATED_DIR}/decisions.md"), decisions_md(root)?);
    files.insert(format!("{GENERATED_DIR}/lab-notes.md"), lab_notes_md(root)?);
    if let Some(inv) = crate::attributes::load(root)? {
        files.insert(
            format!("{GENERATED_DIR}/acn-attributes.md"),
            format!("{HEADER}{}", crate::attributes::page(&inv)),
        );
    }
    if let Some(page) = report_coverage_md(root)? {
        files.insert(format!("{GENERATED_DIR}/report-coverage.md"), page);
    }
    Ok(files)
}

/// Entries of the generated directory that this task did not produce. Only a
/// `.gitkeep` placeholder is tolerated: a hidden file is still stale content.
fn stale_files(root: &Path, generated: &BTreeMap<String, String>) -> Result<Vec<String>> {
    let dir = root.join(GENERATED_DIR);
    Ok(names_in(&dir, |n| n != ".gitkeep")?
        .into_iter()
        .map(|n| format!("{GENERATED_DIR}/{n}"))
        .filter(|key| !generated.contains_key(key))
        .collect())
}

/// An output path must be a regular file or absent. Following a symlink would
/// let this task overwrite a file outside the directory it owns.
fn refuse_symlink(path: &Path) -> Result<()> {
    match std::fs::symlink_metadata(path) {
        Ok(meta) if meta.file_type().is_symlink() => Err(Error::Invalid(format!(
            "{} is a symlink; generated documentation is only written to regular files",
            path.display()
        ))),
        _ => Ok(()),
    }
}

/// Write (or, with `check`, compare) the generated files. Write mode owns the
/// directory: it also removes stale files, so a write is always followed by a passing check.
pub fn run(root: &Path, check: bool) -> Result<Report> {
    let generated = generate(root)?;
    refuse_symlink(&root.join(GENERATED_DIR))?;
    let stale = stale_files(root, &generated)?;
    let mut written = Vec::new();
    let mut changed = Vec::new();
    let mut removed = Vec::new();
    for (path, content) in &generated {
        let target = root.join(path);
        refuse_symlink(&target)?;
        let on_disk = if target.exists() {
            Some(read(&target)?)
        } else {
            None
        };
        if on_disk.as_deref() != Some(content.as_str()) {
            changed.push(path.clone());
            if check {
                tracing::warn!(file = %path, "generated documentation is out of date: run `cargo xtask docs-inventory`");
            } else {
                write(&target, content)?;
                written.push(path.clone());
            }
        }
    }
    for path in &stale {
        if check {
            tracing::warn!(file = %path, "stale file in the generated directory: run `cargo xtask docs-inventory`");
        } else {
            let target = root.join(path);
            let meta = std::fs::symlink_metadata(&target).map_err(|e| Error::io(&target, e))?;
            if meta.is_dir() {
                std::fs::remove_dir_all(&target).map_err(|e| Error::io(&target, e))?;
            } else {
                std::fs::remove_file(&target).map_err(|e| Error::io(&target, e))?;
            }
            removed.push(path.clone());
        }
    }
    let unlisted_attributes = match crate::attributes::load(root)? {
        Some(inv) => crate::attributes::unlisted(root, &inv)?,
        None => Vec::new(),
    };
    for u in &unlisted_attributes {
        tracing::error!(file = %u.file, name = %u.name, "`acn.*` name is not in acn_attributes.toml (TRC-20)");
    }
    let ok = unlisted_attributes.is_empty() && (!check || (changed.is_empty() && stale.is_empty()));
    Ok(Report {
        ok,
        mode: if check { "check" } else { "write" },
        written,
        changed,
        stale,
        removed,
        unlisted_attributes,
    })
}
